const QuantumDisplay = memo(({ q }: { q: QuantumAnalysis }) => {
    if (!q) return null;

    // Determine color based on wave function state
    const isStable = q.waveFunction.includes('Certainty');
    const isVolatile = q.waveFunction.includes('Uncertainty');

    const stateColor = isStable ? 'text-emerald-400' : isVolatile ? 'text-amber-400' : 'text-fuchsia-400';
    const stateBorder = isStable ? 'border-emerald-500/30' : isVolatile ? 'border-amber-500/30' : 'border-fuchsia-500/30';
    const stateBg = isStable ? 'bg-emerald-500/10' : isVolatile ? 'bg-amber-500/10' : 'bg-fuchsia-500/10';

    return (
        <div className="bg-zinc-900/40 border border-zinc-800 rounded-[2rem] p-6 relative overflow-hidden tactical-outline group h-full flex flex-col justify-between">
            {/* Ambient Background Glow */}
            <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500/5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2 group-hover:bg-fuchsia-500/10 transition-colors duration-700 pointer-events-none"></div>

            <div className="flex items-center gap-3 mb-6 relative z-10">
                <div className="w-1.5 h-1.5 bg-fuchsia-500 rounded-full animate-pulse shadow-[0_0_8px_fuchsia]"></div>
                <h4 className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.4em]">Quantum Entanglement</h4>
            </div>

            <div className="relative z-10 flex-1 flex flex-col gap-6">
                 {/* Main State Display */}
                <div className={`rounded-2xl p-4 border ${stateBorder} ${stateBg} backdrop-blur-sm transition-all`}>
                     <span className="text-[8px] font-black text-zinc-500 uppercase tracking-widest block mb-1.5">Wave Function Status</span>
                     <div className={`text-sm font-black uppercase tracking-tight flex items-start gap-2 ${stateColor}`}>
                        <svg className="w-4 h-4 mt-0.5 shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                        </svg>
                        <span className="leading-tight">{q.waveFunction}</span>
                     </div>
                </div>

                {/* Metrics Grid */}
                <div className="grid grid-cols-2 gap-4">
                    {/* Entropy Metric */}
                    <div className="bg-black/20 rounded-xl p-3 border border-zinc-800/50">
                        <div className="flex justify-between items-center mb-2">
                             <span className="text-[8px] font-black text-zinc-500 uppercase tracking-wider">Entropy</span>
                             <span className="text-[10px] font-bold text-fuchsia-400 tabular-nums">{q.entropyScore}</span>
                        </div>
                         <div className="h-1.5 w-full bg-zinc-800 rounded-full overflow-hidden">
                             <div 
                                 className="h-full bg-gradient-to-r from-fuchsia-600 to-purple-600 shadow-[0_0_10px_fuchsia]" 
                                 style={{ width: `${q.entropyScore}%` }}
                             ></div>
                         </div>
                    </div>

                    {/* Volatility Metric */}
                    <div className="bg-black/20 rounded-xl p-3 border border-zinc-800/50">
                        <div className="flex justify-between items-center mb-2">
                             <span className="text-[8px] font-black text-zinc-500 uppercase tracking-wider">Volatility</span>
                             <span className="text-[10px] font-bold text-amber-500 tabular-nums">{q.volatilityIndex}</span>
                        </div>
                         <div className="h-1.5 w-full bg-zinc-800 rounded-full overflow-hidden">
                             <div 
                                 className="h-full bg-gradient-to-r from-rose-500 to-amber-500 shadow-[0_0_10px_orange]" 
                                 style={{ width: `${q.volatilityIndex}%` }}
                             ></div>
                         </div>
                    </div>
                </div>

                {/* Dominant Energy Footer */}
                <div className="mt-auto pt-4 border-t border-zinc-800/50">
                    <span className="text-[8px] font-black text-zinc-600 uppercase tracking-widest block mb-1.5">Dominant Energy Signature</span>
                    <div className="flex items-start gap-2 text-zinc-300">
                        <svg className="w-3 h-3 mt-0.5 text-zinc-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        <p className="text-[10px] font-medium italic leading-relaxed">
                            "{q.dominantEnergy}"
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
});

