            {/* Best Bet / Alpha Lock Section */}
            {prediction.bestBet && <BestBetDisplay bet={prediction.bestBet} />}

            {/* Main Winner Card */}
             <div className={`relative ${confidence.bg} border-2 ${confidence.border} rounded-[3rem] p-8 md:p-12 overflow-hidden shadow-2xl group`}>
                <CardAccent />
                <div className={`absolute top-0 right-0 p-8 opacity-10 transition-transform duration-1000 group-hover:scale-110 group-hover:rotate-3 ${confidence.text}`}>
                    <LogoIcon className="w-64 h-64" />
