                <div className="relative z-10 flex flex-col items-center text-center space-y-6">
                     <div className={`px-4 py-1.5 rounded-full border ${confidence.border} ${confidence.accent} bg-opacity-10 backdrop-blur-md flex items-center gap-2 shadow-lg`}>
                        <div className={`w-2 h-2 rounded-full ${confidence.accent} animate-pulse shadow-[0_0_10px_currentColor]`}></div>
                        <span className={`text-[10px] font-black uppercase tracking-[0.3em] ${confidence.text}`}>
                            Confidence: {prediction.confidence} ({Math.round(prediction.confidenceScore * 100)}%)
                        </span>
                     </div>

                     <div className="space-y-2">
                        <span className="text-sm font-black text-zinc-500 uppercase tracking-[0.5em]">Projected Winner</span>
                        <h2 className="text-5xl md:text-7xl font-black text-white italic tracking-tighter uppercase drop-shadow-2xl">
                            {prediction.winner}
