                                        className={`h-full rounded-l-full transition-all duration-1000 ${stat.advantage === 'Home' ? 'bg-indigo-500 shadow-[0_0_10px_indigo]' : 'bg-zinc-700'}`} 
                                        style={{ width: `${isNaN(hPercent) ? 0 : hPercent}%` }}
                                    ></div>
                                </div>
                                <div className="flex-1 flex justify-start bg-zinc-800/50">
                                    <div 
                                        className={`h-full rounded-r-full transition-all duration-1000 ${stat.advantage === 'Away' ? 'bg-indigo-500 shadow-[0_0_10px_indigo]' : 'bg-zinc-700'}`} 
